// === Tab: mySketch ===
// 変数の定義
let a = 3;
let b = 4;
let c = 5;
let angle = 0;

// スライダーとラベル用の変数
let sliderA, sliderB, sliderC;
let labelA, labelB, labelC;

function setup() {
  // WEBGLモードでキャンバスを作成
  createCanvas(windowWidth, windowHeight, WEBGL);

  // 色空間をHSBに設定
  colorMode(HSB, 360, 100, 100);

  noFill();
  strokeWeight(2);

  // --- スライダーの作成 (最小値, 最大値, 初期値, ステップ) ---
  // 1〜20の間で変化させる設定にします
  sliderA = createSlider(1, 20, 3, 1);
  sliderB = createSlider(1, 20, 4, 1);
  sliderC = createSlider(1, 20, 5, 1);

  // --- ラベルの作成 ---
  labelA = createDiv('a (X freq)');
  labelB = createDiv('b (Y freq)');
  labelC = createDiv('c (Z freq)');

  // スライダーとラベルの配置を行う関数を呼び出し
  positionUI();
}

function draw() {
  background(220); 

  // --- スライダーの値をプログラムに反映 ---
  a = sliderA.value();
  b = sliderB.value();
  c = sliderC.value();

  // ラベルのテキストを現在の値に更新
  labelA.html(`a: ${a}`);
  labelB.html(`b: ${b}`);
  labelC.html(`c: ${c}`);

  // マウス操作でカメラを動かせるようにする
  orbitControl();

  // 全体をゆっくり回転させる
  rotateY(angle);
  rotateX(angle * 0.5);
  angle += 0.005;

  // リサージュカーブの描画 (提供されたコードを使用)
  for (let t = 0; t < 360 * 2; t += 0.5) {

    let rad = radians(t);
    let r = max(width, height) / 3;

    let x = r * sin(a * rad);
    let y = r * sin(b * rad);
    let z = r * sin(c * rad);

    // 色を角度によって変化させる
    stroke(t % 360, 80, 100);
    fill(t % 360, 80, 100);


    // 頂点を配置 (提供されたbox描画ロジック)
    push();
    translate(x, y, z);
    box(8);
    pop();
  }
}

// UIの配置を行う関数（初期化時とリサイズ時に使うため分離）
function positionUI() {
  var x = 20; // 画面左からの距離
  var y = windowHeight / 2; // 画面中央の高さ
  let gap = 50; // スライダー間の隙間

  // スライダーBを画面中央(height/2)に配置
  // ※WEBGLモードでもDOM要素(スライダー)は画面左上が(0,0)です

  // Slider A
  sliderA.position(x, y - gap);
  labelA.position(x + 140, y - gap); // スライダーの右横に数値を置く

  // Slider B (中央)
  sliderB.position(x, y);
  labelB.position(x + 140, y);

  // Slider C
  sliderC.position(x, y + gap);
  labelC.position(x + 140, y + gap);
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  positionUI(); // ウィンドウサイズが変わったらスライダー位置も再計算
}

